"""
network_report.py
------------------
Renders the nginx-log-derived CSV (produced by parse_log.py) as a Markdown
table, one section per technology.

Usage:
  python network_report.py <results.csv> [output.md]
"""

import sys
import pandas as pd

CSV_FIELDS_ORDER = [
    "scale_factor", "query_id", "duration_s", "n_requests", "total_bytes_mb",
]


def build(csv_path: str, md_path: str) -> None:
    df = pd.read_csv(csv_path)

    lines = ["# Network Capture (nginx access log)", "",
             "> Auto-generated by `network_report.py`", ""]

    if df.empty:
        lines.append("_No sentinel-bounded requests found in the access log._")
    else:
        for tech, group in df.groupby("technology"):
            lines.append(f"## {tech}")
            lines.append("")
            table = group[CSV_FIELDS_ORDER].sort_values(["scale_factor", "query_id"])
            lines.append(table.to_markdown(index=False))
            lines.append("")

    with open(md_path, "w") as f:
        f.write("\n".join(lines) + "\n")

    print(f"  Network report written -> {md_path}")


if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python network_report.py <results.csv> [output.md]")
        sys.exit(1)
    build(sys.argv[1], sys.argv[2] if len(sys.argv) > 2 else "network-summary.md")
